BEGIN;
CREATE TABLE IF NOT EXISTS mission_bridge_languages(locale TEXT PRIMARY KEY,display_name TEXT NOT NULL,script TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',is_core BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS mission_bridge_translation_reviews(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,localization_version_id UUID NOT NULL REFERENCES mission_bridge_localization_versions(id),review_type TEXT NOT NULL CHECK(review_type IN('human_translation','local_culture','theological_terms')),decision TEXT NOT NULL CHECK(decision IN('approved','changes_requested')),reviewer_user_id TEXT NOT NULL,notes TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(localization_version_id,review_type));
CREATE TABLE IF NOT EXISTS mission_bridge_theological_glossary(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,concept_key TEXT NOT NULL,locale TEXT NOT NULL,preferred_term TEXT NOT NULL,plain_explanation TEXT NOT NULL,reviewed BOOLEAN NOT NULL DEFAULT FALSE,UNIQUE(tenant_id,concept_key,locale));
CREATE TABLE IF NOT EXISTS mission_bridge_dialect_audio(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,localization_version_id UUID NOT NULL REFERENCES mission_bridge_localization_versions(id),locale TEXT NOT NULL,dialect_name TEXT NOT NULL,audio_url TEXT NOT NULL,text_version_id UUID NOT NULL REFERENCES mission_bridge_content_versions(id),narrator_name TEXT NOT NULL,attribution_choice TEXT NOT NULL CHECK(attribution_choice IN('full_name','pseudonym','anonymous')),license TEXT NOT NULL,model_training_consent BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_localization_principles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),principle_key TEXT UNIQUE NOT NULL,description TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
ALTER TABLE mission_bridge_translation_reviews ENABLE ROW LEVEL SECURITY;CREATE POLICY tenant_isolation ON mission_bridge_translation_reviews USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));ALTER TABLE mission_bridge_theological_glossary ENABLE ROW LEVEL SECURITY;CREATE POLICY tenant_isolation ON mission_bridge_theological_glossary USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));ALTER TABLE mission_bridge_dialect_audio ENABLE ROW LEVEL SECURITY;CREATE POLICY tenant_isolation ON mission_bridge_dialect_audio USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
INSERT INTO mission_bridge_languages(locale,display_name,script,is_core) VALUES('zh-CN','简体中文','Hans',TRUE),('zh-TW','繁體中文','Hant',TRUE),('en','English','Latn',TRUE) ON CONFLICT DO NOTHING;
INSERT INTO mission_bridge_localization_principles(principle_key,description) VALUES('no_single_standard','不把汉语标准版本强制视为唯一正确表达'),('no_ability_label','不因简化语言把人描述成低能力'),('audio_training_opt_in','不未经同意采集少数语言音频作为模型训练数据'),('narrator_rights','本地讲述者拥有署名和许可选择') ON CONFLICT DO NOTHING;
COMMIT;
